const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const ext=name=>(name.split('.').pop()||'').toLowerCase();
const toastRegion=$('#toastRegion');
function toast(message,type=''){const d=document.createElement('div');d.className=`toast ${type}`;d.textContent=message;toastRegion.append(d);setTimeout(()=>d.remove(),3400);}
function uid(p='asset'){return `${p}_${crypto.randomUUID()}`;}
function bytes(n){if(!Number.isFinite(n))return '—';const u=['B','KB','MB','GB'];let i=0;while(n>=1024&&i<u.length-1){n/=1024;i++;}return `${n.toFixed(i?1:0)} ${u[i]}`;}
function setSaveStatus(text){const el=$('#saveStatus');if(el)el.innerHTML=`<i aria-hidden="true"></i><span>${esc(text)}</span>`;}

const audio=new AudioEngine();
const runtime={assetElements:new Map(),assetUrls:new Map(),audioBlob:null,peaks:[],bpm:0,guides:true,loopEnabled:false,loopRange:null,previewZoom:1,transcriptionProviderFactory:null};
let state=new EditorState(createProject('Untitled Project'));
let leftTab='media', searchLyrics='', tapSyncIndex=0, autosaveTimer=null, renderRAF=0, lastRenderProjectVersion=0;
let dragState=null, boxState=null, canvasGesture=null, cropMode=null, styleClipboard=null;
let presetMode='factory', installedPresets=[], presetCatalog=[], presetCatalogStatus='idle', presetQuery='', presetCategory='all', presetSelection={kind:'factory',id:PRESETS[0]?.id||null};

const canvas=$('#previewCanvas'), ctx=canvas.getContext('2d',{alpha:false}), stage=$('#stage');
const isCompactMobile=()=>matchMedia('(max-width:820px)').matches;
const isPortraitMobile=()=>matchMedia('(max-width:820px) and (orientation:portrait)').matches;
const left=$('#leftContent'), inspector=$('#inspector');
const modal=$('#modal'), modalBody=$('#modalBody');
const timelineContent=$('#timelineContent'), timelineScroll=$('#timelineScroll');
const canvasSelection=$('#canvasSelection'), selectionFrame=$('#selectionFrame'), selectionToolbar=canvasSelection?.querySelector('.selection-toolbar'), alignmentGuides=$('#alignmentGuides'), cropToolbar=$('#cropToolbar'), timelineContextSheet=$('#timelineContextSheet');

function projectDuration(){return Math.max(1_000_000,state.project.durationUs||180_000_000);}
function pxPerUs(){return (60 * Number($('#timelineZoom').value||1))/1_000_000;}
function xForUs(us){return us*pxPerUs();}
function usForX(x){return Math.max(0,Math.round(x/pxPerUs()));}
function activeLyricIndex(time=state.playheadUs){const s=[...state.project.lyrics].sort((a,b)=>a.startUs-b.startUs);let i=s.findIndex(e=>time>=e.startUs&&time<e.endUs);if(i<0)i=s.findLastIndex?.(e=>e.startUs<=time)??-1;return {sorted:s,index:i,event:i>=0?s[i]:null};}
function selectedLyric(){const id=[...state.selected.lyrics][0];return id?state.project.lyrics.find(e=>e.id===id):null;}
function selectedClip(){const id=[...state.selected.clips][0];return id?state.project.clips.find(c=>c.id===id):null;}

function projectChanged(){
  $('#projectNameTop').textContent=state.project.name;setSaveStatus(`Local · ${state.dirty?'unsaved changes':'saved'}`);
  const c=state.project.composition;$('#compositionLabel').textContent=`${c.width}×${c.height} · ${c.aspect}`;canvas.width=c.width;canvas.height=c.height;canvas.style.aspectRatio=`${c.width}/${c.height}`;
  renderLeft();renderInspector();renderTimeline();updateGuide();scheduleAutosave();renderFrame();renderSelectionOverlay();
}
function selectionChanged(){renderLeft();renderInspector();renderTimeline();renderSelectionOverlay();}
function playheadChanged(){updatePlayhead();renderFrame();updateTime();}
state.addEventListener('change',projectChanged);state.addEventListener('selection',selectionChanged);state.addEventListener('playhead',playheadChanged);state.addEventListener('saved',()=>setSaveStatus('Local · saved'));

function updateGuide(){const hasAudio=!!state.project.audioMasterAssetId,hasLyrics=state.project.lyrics.length>0,styled=state.project.lyricStyle?.activeColor!=='#ff365c'||state.project.visualizer?.enabled;const steps=$$('.guide button[data-guide]');for(const b of steps){const k=b.dataset.guide;b.classList.toggle('done',(k==='media'&&hasAudio)||(k==='lyrics'&&hasLyrics)||(k==='presets'&&styled));b.classList.toggle('current',(k==='media'&&!hasAudio)||(k==='lyrics'&&hasAudio&&!hasLyrics)||(k==='presets'&&hasLyrics&&!styled)||(k==='adjust'&&hasLyrics&&styled));}}

function scheduleAutosave(){clearTimeout(autosaveTimer);if(!state.dirty)return;autosaveTimer=setTimeout(async()=>{try{await saveProject(state.project);state.markSaved();}catch(e){toast(`Autosave failed: ${e.message}`,'bad');}},1600);}
async function saveNow(){try{await saveProject(state.project);state.markSaved();toast('Project saved locally','good');}catch(e){toast(e.message,'bad');}}

function renderLeft(){
  $$('.tool-rail button').forEach(b=>b.classList.toggle('active',b.dataset.tab===leftTab));
  if(leftTab==='media')left.innerHTML=mediaPanel();
  else if(leftTab==='lyrics')left.innerHTML=lyricsPanel();
  else if(leftTab==='text')left.innerHTML=textPanel();
  else if(leftTab==='presets')left.innerHTML=presetsPanel();
  else if(leftTab==='effects')left.innerHTML=effectsPanel();
  else left.innerHTML=elementsPanel();
}
function mediaPanel(){return `<div class="section"><h3>Project media</h3><div class="drop-card"><b>Drop files anywhere</b><span class="subtle">Audio, video, images, lyric files, project fonts</span><button class="primary" data-left="import">Import media</button></div></div><div class="section"><div class="row spread"><h3 style="margin:0">Assets</h3><small class="subtle">${state.project.assets.length}</small></div><div class="stack">${state.project.assets.map(a=>`<div class="asset-card"><span class="asset-icon">${a.type==='audio'?'♪':a.type==='video'?'▶':a.type==='image'?'▧':a.type==='font'?'Aa':'•'}</span><div><b title="${esc(a.name)}">${esc(a.name)}</b><small>${esc(a.type)}${a.role?` · ${esc(a.role)}`:''}</small></div><div class="row">${(a.type==='image'||a.type==='video')?`<button data-left="add-media-layer" data-id="${a.id}" title="Add as timeline layer">＋</button><button data-left="set-background" data-id="${a.id}" title="Use as background">BG</button>`:''}</div></div>`).join('')||'<p class="subtle">Nothing imported yet.</p>'}</div></div><div class="section"><h3>Project files</h3><div class="row"><button data-left="import-project">Import project</button><button data-left="export-project">Export project</button></div></div>`;}
function lyricsPanel(){const lines=state.project.lyrics.filter(e=>!searchLyrics||e.text.toLowerCase().includes(searchLyrics.toLowerCase()));const support=browserWhisperSupport();return `<div class="section ai-section"><div class="section-heading"><div><span class="eyebrow">LYRIC AI</span><h3>Automatic transcription</h3></div><span class="privacy-badge">● Local</span></div><button class="primary ai-launch" data-left="auto-detect"><span class="ai-spark">✦</span><span><b>Auto Detect Lyrics</b><small>No API key · word timing · editable</small></span><span class="chevron">›</span></button><div class="ai-facts"><span>Runs on this device</span><span>${support.device==='webgpu'?'WebGPU acceleration':'WASM fallback'}</span></div><p class="subtle">On first use LyricForge downloads a small Whisper model, then your browser caches it for later sessions. Your song is not uploaded in built-in mode.</p></div><div class="section"><div class="section-heading"><h3>Paste / type lyrics</h3><span class="section-kicker">Manual</span></div><textarea id="lyricPaste" placeholder="Paste one lyric line per row…"></textarea><div class="row"><button data-left="add-pasted">Create lyric events</button><button data-left="add-line">Add line</button></div></div><div class="section"><div class="section-heading"><h3>Manual synchronization</h3><span class="section-kicker">Tap to time</span></div><div class="three-col sync-grid"><button data-left="set-start">Set Start</button><button data-left="set-end">Set End</button><button data-left="snap-playhead">Snap</button><button data-left="prev-line">Prev</button><button class="primary" data-left="tap-sync">Tap Sync</button><button data-left="next-line">Next</button><button data-left="nudge-earlier">− Nudge</button><button data-left="nudge-later">+ Nudge</button><button data-left="merge">Merge</button></div><p class="subtle">Start playback, select the first line, then press Tap Sync whenever the next lyric begins.</p></div><div class="section"><div class="row lyric-search-row"><input id="lyricSearch" type="text" value="${esc(searchLyrics)}" placeholder="Search lyrics…"><button data-left="low-confidence" title="Show confidence warnings">⚠</button></div><div class="lyric-list">${lines.map(e=>`<div class="lyric-row ${state.selected.lyrics.has(e.id)?'selected':''}" data-lyric-id="${e.id}"><time>${formatClock(e.startUs,false)}</time><input data-line-text="${e.id}" value="${esc(e.text)}"><span class="confidence ${e.confidence<.75?'low':''}">${Math.round((e.confidence??1)*100)}%</span></div>`).join('')||'<div class="empty-state compact"><span>♪</span><b>No lyrics yet</b><small>Auto-detect them, paste text, or add a line manually.</small></div>'}</div></div>`;}
function textPanel(){return `<div class="section"><h3>Text layers</h3><button class="primary" style="width:100%" data-left="add-title">+ Add title / text</button><p class="subtle">Additional text is independent from lyrics and can be timed, dragged and keyframed.</p></div><div class="section"><h3>Global lyric typography</h3>${textStyleFields(state.project.lyricStyle,'global')}</div>`;}
function presetsPanel(){
  const modes=`<div class="preset-mode-tabs"><button data-left="preset-mode" data-mode="factory" class="${presetMode==='factory'?'active':''}">Factory</button><button data-left="preset-mode" data-mode="installed" class="${presetMode==='installed'?'active':''}">Installed</button><button data-left="preset-mode" data-mode="library" class="${presetMode==='library'?'active':''}">Library</button></div>`;
  const actions=`<div class="row preset-file-actions"><button data-left="import-preset">Import Preset</button><button data-left="export-preset">Export Preset</button></div>`;
  let body='';
  if(presetMode==='factory')body=`<div class="section"><h3>Factory presets</h3><div class="preset-grid">${PRESETS.map(p=>`<div class="preset-card ${presetSelection.kind==='factory'&&presetSelection.id===p.id?'selected':''}" data-preset="${p.id}" style="--p-bg:${p.background};--p-accent:${p.accent}"><b>${p.name}</b><span>${p.entrance} · ${p.karaoke}</span></div>`).join('')}</div></div><div class="section"><h3>Project custom presets</h3><button data-left="save-preset">Save current style</button><div class="stack" style="margin-top:7px">${(state.project.customPresets||[]).map((p,i)=>`<button data-custom-preset="${i}">${esc(p.name)}</button>`).join('')||'<p class="subtle">Save your current typography, background and visualizer as a reusable project preset.</p>'}</div></div>`;
  if(presetMode==='installed')body=`<div class="section"><div class="row spread"><h3 style="margin:0">Installed presets</h3><button data-left="refresh-installed">Refresh</button></div><div class="preset-grid installed-grid">${installedPresets.map(p=>`<div class="preset-card installed ${presetSelection.kind==='installed'&&presetSelection.id===p.id?'selected':''}" data-installed-preset="${esc(p.id)}" style="--p-bg:${Array.isArray(p.background?.value)?p.background.value[0]:p.background?.value||'#10131d'};--p-accent:${p.accent||p.style?.activeColor||'#8d5cff'}"><b>${esc(p.name)}</b><span>${esc(p.author)} · v${esc(p.version)}</span><button data-left="remove-installed" data-id="${esc(p.id)}">Remove</button></div>`).join('')||'<div class="empty-state compact"><span>✦</span><b>No installed presets</b><small>Import a .lyricpreset file or install one from Library.</small></div>'}</div></div>`;
  if(presetMode==='library'){const categories=['all',...new Set(presetCatalog.map(p=>p.category).filter(Boolean))];const rows=searchPresetCatalog(presetCatalog,{query:presetQuery,category:presetCategory});body=`<div class="section"><div class="row spread"><h3 style="margin:0">Preset Library</h3><button data-left="refresh-library">Refresh</button></div><div class="two-col"><input id="presetLibrarySearch" placeholder="Search presets…" value="${esc(presetQuery)}"><select id="presetLibraryCategory">${categories.map(c=>`<option value="${esc(c)}" ${presetCategory===c?'selected':''}>${c==='all'?'All categories':esc(c)}</option>`).join('')}</select></div><p class="subtle">${presetCatalogStatus==='loading'?'Loading catalog…':presetCatalogStatus==='error'?'Library is offline. Factory and Installed presets still work.':`${rows.length} available presets`}</p><div class="preset-library-list">${rows.map(p=>{const installed=installedPresets.find(x=>x.id===p.id);const stateText=installed?(installed.version===p.version?'Installed':'Update'):'Install';return `<article class="library-preset"><div><b>${esc(p.name)}</b><small>${esc(p.author)} · ${esc(p.category)} · v${esc(p.version)}</small></div><button data-left="install-library" data-id="${esc(p.id)}">${stateText}</button></article>`}).join('')||'<div class="empty-state compact"><span>⌕</span><b>No presets found</b><small>Try another search or refresh the catalog.</small></div>'}</div></div>`;}
  return `<div class="section preset-library-header"><span class="eyebrow">PRESET ECOSYSTEM</span><h3>Looks & motion</h3>${modes}${actions}</div>${body}`;
}
function effectsPanel(){
  const v=state.project.visualizer,b=state.project.background,fx=normalizeVideoEffects(state.project.videoEffects);
  const grouped=Object.groupBy?Object.groupBy(VIDEO_EFFECTS,e=>e.group):VIDEO_EFFECTS.reduce((m,e)=>((m[e.group]??=[]).push(e),m),{});
  const effectHtml=Object.entries(grouped).map(([group,items])=>`<div class="effect-group"><h4>${esc(group)}</h4><div class="effect-grid">${items.map(e=>`<label class="effect-card"><span><b>${esc(e.name)}</b><small>${e.signed?'Cold ← → Warm':'Intensity'}</small></span><input type="range" min="${e.signed?-1:0}" max="1" step=".05" value="${fx[e.id]??0}" data-project="videoEffects.${e.id}"></label>`).join('')}</div></div>`).join('');
  return `<div class="section"><h3>Text / lyric effects</h3><div class="text-effect-grid">${TEXT_EFFECT_PRESETS.map(e=>`<button data-text-effect="${e.id}">${esc(e.name)}</button>`).join('')}</div><p class="subtle">Applies to the selected text layer, or to global lyrics when no text layer is selected.</p></div><div class="section"><div class="row spread"><h3 style="margin:0">Whole-video effects</h3><button data-left="reset-effects">Reset</button></div><p class="subtle">These render through the same composition pipeline used by preview and export.</p>${effectHtml}<label class="field"><span>Tint color</span><input type="color" value="${fx.tintColor||'#ff3b7b'}" data-project="videoEffects.tintColor"></label></div><div class="section"><h3>Music visualizer</h3><label class="field"><span>Type</span><select data-project="visualizer.type"><option value="bars" ${v.type==='bars'?'selected':''}>Audio Bars</option><option value="spectrum" ${v.type==='spectrum'?'selected':''}>Spectrum</option><option value="circular" ${v.type==='circular'?'selected':''}>Circular Spectrum</option><option value="pulse" ${v.type==='pulse'?'selected':''}>Pulsing Glow</option></select></label><label class="row"><input type="checkbox" data-project="visualizer.enabled" ${v.enabled?'checked':''}> Enable visualizer</label><label class="field"><span>Sensitivity</span><input type="range" min=".2" max="3" step=".1" value="${v.sensitivity}" data-project="visualizer.sensitivity"></label><label class="field"><span>Opacity</span><input type="range" min="0" max="1" step=".05" value="${v.opacity}" data-project="visualizer.opacity"></label><label class="field"><span>Color</span><input type="color" value="${v.color}" data-project="visualizer.color"></label></div><div class="section"><h3>Background treatment</h3><label class="field"><span>Fit</span><select data-project="background.fit"><option ${b.fit==='cover'?'selected':''}>cover</option><option ${b.fit==='contain'?'selected':''}>contain</option><option ${b.fit==='stretch'?'selected':''}>stretch</option></select></label>${['blur','brightness','contrast','saturation','hue','vignette'].map(k=>`<label class="field"><span>${k[0].toUpperCase()+k.slice(1)}</span><input type="range" data-project="background.${k}" value="${b[k]??0}" min="${k==='hue'?-180:0}" max="${k==='blur'?30:k==='hue'?180:2}" step="${k==='blur'||k==='hue'?1:.05}"></label>`).join('')}</div>`;
}
function elementsPanel(){return `<div class="section"><h3>Markers</h3><button data-left="marker">+ Marker at playhead</button><div class="stack" style="margin-top:8px">${state.project.markers.map(m=>`<div class="asset-card"><span class="asset-icon">◆</span><div><b>${esc(m.label)}</b><small>${formatClock(m.timeUs)}</small></div></div>`).join('')||'<p class="subtle">Markers help with snapping and structure.</p>'}</div></div><div class="section"><h3>Layer controls</h3><p class="subtle">Use the timeline track eye/lock/mute controls to manage layers. Additional text, images, backgrounds, overlays and effects remain separate objects.</p></div>`;}
function fontOptions(current){
  const system=[
    ['Inter, system-ui, sans-serif','Inter / System'],
    ['Arial Black, sans-serif','Arial Black'],
    ['Impact, sans-serif','Impact']
  ];
  const a=system.map(([value,label])=>`<option value="${esc(value)}" ${current===value||String(current).startsWith(value.split(',')[0])?'selected':''}>${label}</option>`).join('');
  const b=WEB_FONTS.map(f=>{const value=fontStack(f.family);return `<option value="${esc(value)}" ${current===value?'selected':''}>${esc(f.family)} · Web Font</option>`;}).join('');
  const c=state.project.fonts.map(f=>`<option value="${esc(f.family)}" ${current===f.family?'selected':''}>${esc(f.family)} · Project Font</option>`).join('');
  return `<optgroup label="Built in">${a}</optgroup><optgroup label="Web fonts">${b}</optgroup>${c?`<optgroup label="Project fonts">${c}</optgroup>`:''}`;
}
function loadWebFontsForProject(){
  const values=[state.project.lyricStyle?.fontFamily,state.project.titleStyle?.fontFamily,...state.project.clips.filter(c=>c.type==='text').map(c=>c.content?.style?.fontFamily)].filter(Boolean);
  for(const value of new Set(values))ensureWebFont(value).then(ok=>{if(ok)renderFrame();}).catch(()=>{});
}
function textStyleFields(s,scope){const anim=(slot)=>`<select data-style="${scope}:${slot}.name">${ANIMATIONS.map(x=>`<option value="${x}" ${s[slot]?.name===x?'selected':''}>${x}</option>`).join('')}</select>`;return `<label class="field"><span>Font</span><select data-style="${scope}:fontFamily">${fontOptions(s.fontFamily)}</select></label><div class="two-col"><label class="field"><span>Size</span><input type="number" value="${s.fontSize}" data-style="${scope}:fontSize"></label><label class="field"><span>Weight</span><select data-style="${scope}:fontWeight">${[400,600,800,900].map(w=>`<option value="${w}" ${Number(s.fontWeight)===w?'selected':''}>${w}</option>`).join('')}</select></label></div><div class="two-col"><label class="row"><input type="checkbox" ${s.italic?'checked':''} data-style="${scope}:italic"> Italic</label><label class="row"><input type="checkbox" ${s.underline?'checked':''} data-style="${scope}:underline"> Underline</label></div><label class="field"><span>Capitalization</span><select data-style="${scope}:textTransform"><option value="none" ${s.textTransform==='none'?'selected':''}>As typed</option><option value="uppercase" ${s.textTransform==='uppercase'?'selected':''}>UPPERCASE</option><option value="lowercase" ${s.textTransform==='lowercase'?'selected':''}>lowercase</option></select></label><div class="three-col"><label class="field"><span>Letter</span><input type="number" step=".5" value="${s.letterSpacing||0}" data-style="${scope}:letterSpacing"></label><label class="field"><span>Word</span><input type="number" step=".5" value="${s.wordSpacing||0}" data-style="${scope}:wordSpacing"></label><label class="field"><span>Line</span><input type="number" step=".05" value="${s.lineHeight||1.1}" data-style="${scope}:lineHeight"></label></div><div class="two-col"><label class="field"><span>Text color</span><input type="color" value="${s.color}" data-style="${scope}:color"></label><label class="field"><span>Active color</span><input type="color" value="${s.activeColor||s.color}" data-style="${scope}:activeColor"></label></div><label class="row"><input type="checkbox" ${s.gradientEnabled?'checked':''} data-style="${scope}:gradientEnabled"> Gradient text</label><div class="two-col"><label class="field"><span>Gradient start</span><input type="color" value="${s.gradientStart||s.color}" data-style="${scope}:gradientStart"></label><label class="field"><span>Gradient end</span><input type="color" value="${s.gradientEnd||s.activeColor||s.color}" data-style="${scope}:gradientEnd"></label></div><div class="three-col"><label class="field"><span>Stroke</span><input type="number" min="0" max="20" value="${s.strokeWidth}" data-style="${scope}:strokeWidth"></label><label class="field"><span>Shadow</span><input type="number" min="0" max="80" value="${s.shadowBlur||0}" data-style="${scope}:shadowBlur"></label><label class="field"><span>Glow</span><input type="number" min="0" max="80" value="${s.glow||0}" data-style="${scope}:glow"></label></div><div class="three-col"><label class="field"><span>Opacity</span><input type="number" min="0" max="1" step=".05" value="${s.opacity??1}" data-style="${scope}:opacity"></label><label class="field"><span>Blur</span><input type="number" min="0" max="40" value="${s.blur||0}" data-style="${scope}:blur"></label><label class="field"><span>Padding</span><input type="number" min="0" max="80" value="${s.padding||0}" data-style="${scope}:padding"></label></div><div class="two-col"><label class="field"><span>Box opacity</span><input type="number" min="0" max="1" step=".05" value="${s.backgroundOpacity||0}" data-style="${scope}:backgroundOpacity"></label><label class="field"><span>Corner radius</span><input type="number" min="0" max="80" value="${s.radius||0}" data-style="${scope}:radius"></label></div><label class="field"><span>Karaoke</span><select data-style="${scope}:karaoke"><option value="word-highlight" ${s.karaoke==='word-highlight'?'selected':''}>Word highlight</option><option value="current-word-scale" ${s.karaoke==='current-word-scale'?'selected':''}>Current word larger</option><option value="progressive-fill" ${s.karaoke==='progressive-fill'?'selected':''}>Progressive fill</option><option value="full-line" ${s.karaoke==='full-line'?'selected':''}>Full line</option></select></label><details><summary>Animation</summary><label class="field"><span>Entrance</span>${anim('entrance')}</label><label class="field"><span>Idle</span>${anim('idle')}</label><label class="field"><span>Exit</span>${anim('exit')}</label><div class="two-col"><label class="field"><span>Entrance ms</span><input type="number" value="${s.entrance?.durationMs||280}" data-style="${scope}:entrance.durationMs"></label><label class="field"><span>Exit ms</span><input type="number" value="${s.exit?.durationMs||240}" data-style="${scope}:exit.durationMs"></label></div></details>`;}
function objectCommandHtml(clip){const media=clip.type==='image'||clip.type==='video',grouped=!!clip.groupId;return `<div class="section object-commands"><h3>Object commands</h3><div class="command-grid">${media?'<button data-inspect-action="flip-x">Flip X</button><button data-inspect-action="flip-y">Flip Y</button>':''}<button data-inspect-action="duplicate">Duplicate</button><button data-inspect-action="front">Front</button><button data-inspect-action="forward">Forward</button><button data-inspect-action="backward">Backward</button><button data-inspect-action="back">Back</button><button data-inspect-action="group">${grouped?'Ungroup':'Group'}</button><button data-inspect-action="lock">${clip.locked?'Unlock':'Lock'}</button><button data-inspect-action="copy-style">Copy Style</button><button data-inspect-action="paste-style" ${styleClipboard?'':'disabled'}>Paste Style</button><button data-inspect-action="reset">Reset</button>${media?'<button data-inspect-action="crop">Crop</button>':''}</div></div>`;}
function clipTimingHtml(clip){return `<div class="section"><h3>Timeline clip</h3><label class="field"><span>Label</span><input value="${esc(clip.label||'')}" data-clip-meta="label" placeholder="Clip label"></label><div class="two-col"><label class="field"><span>Start ms</span><input type="number" value="${usToMs(clip.startUs)}" data-inspect="clip.start"></label><label class="field"><span>End ms</span><input type="number" value="${usToMs(clip.endUs)}" data-inspect="clip.end"></label><label class="field"><span>Fade in ms</span><input type="number" min="0" value="${usToMs(clip.fadeInUs||0)}" data-clip-meta="fadeIn"></label><label class="field"><span>Fade out ms</span><input type="number" min="0" value="${usToMs(clip.fadeOutUs||0)}" data-clip-meta="fadeOut"></label></div><button data-inspect-action="add-keyframe">Toggle opacity keyframe at playhead</button></div>`;}
function renderInspector(){const lyric=selectedLyric(),clip=selectedClip();if(lyric){inspector.innerHTML=`<div class="section"><h3>Lyric line</h3><label class="field"><span>Text</span><textarea data-inspect="lyric.text">${esc(lyric.text)}</textarea></label><div class="two-col"><label class="field"><span>Start ms</span><input type="number" step="1" value="${usToMs(lyric.startUs)}" data-inspect="lyric.start"></label><label class="field"><span>End ms</span><input type="number" step="1" value="${usToMs(lyric.endUs)}" data-inspect="lyric.end"></label></div><label class="field"><span>Section</span><select data-inspect="lyric.section">${['intro','verse','pre-chorus','chorus','post-chorus','bridge','breakdown','instrumental','outro','unknown'].map(x=>`<option ${lyric.sectionType===x?'selected':''}>${x}</option>`).join('')}</select></label><div class="row"><button data-inspect-action="split">Split</button><button data-inspect-action="duplicate">Duplicate</button><button data-inspect-action="delete">Delete</button></div></div><div class="section"><h3>Word timing ${lyric.words?.length?`· ${lyric.words.length}`:''}</h3>${lyric.words?.length?`<div class="word-table">${lyric.words.map(w=>`<div class="word-row"><input value="${esc(w.text)}" data-word="${w.id}:text"><input type="number" value="${usToMs(w.startUs)}" data-word="${w.id}:start"><input type="number" value="${usToMs(w.endUs)}" data-word="${w.id}:end"></div>`).join('')}</div>`:'<p class="subtle">Word timing appears here after transcription and remains editable.</p>'}</div>`;return;}
  if(clip&&clip.type==='text'){const st={...state.project.titleStyle,...clip.content?.style};inspector.innerHTML=`<div class="section"><h3>Text layer</h3><label class="field"><span>Text</span><textarea data-inspect="clip.text">${esc(clip.content?.text||'')}</textarea></label></div>${clipTimingHtml(clip)}<div class="section"><h3>Typography</h3>${textStyleFields(st,'clip')}</div><div class="section"><h3>Transform</h3><div class="two-col"><label class="field"><span>X</span><input type="number" step=".01" value="${st.x}" data-style="clip:x"></label><label class="field"><span>Y</span><input type="number" step=".01" value="${st.y}" data-style="clip:y"></label><label class="field"><span>Scale</span><input type="number" step=".05" value="${st.scale}" data-style="clip:scale"></label><label class="field"><span>Rotation</span><input type="number" value="${st.rotation}" data-style="clip:rotation"></label></div></div>${objectCommandHtml(clip)}`;return;}
  if(clip){const t=clip.transform||{x:.5,y:.5,scale:1,rotation:0},c=normalizeCrop(clip.crop||{});inspector.innerHTML=`<div class="section"><h3>${clip.type==='image'?'Image':'Video'} layer</h3><p class="subtle">Drag the layer directly in preview. Resize, rotate, crop and layer it precisely below.</p></div>${clipTimingHtml(clip)}<div class="section"><h3>Transform</h3><div class="two-col"><label class="field"><span>X</span><input data-clip-transform="x" type="number" step=".01" value="${t.x}"></label><label class="field"><span>Y</span><input data-clip-transform="y" type="number" step=".01" value="${t.y}"></label><label class="field"><span>Scale</span><input data-clip-transform="scale" type="number" step=".05" value="${t.scale}"></label><label class="field"><span>Rotation</span><input data-clip-transform="rotation" type="number" value="${t.rotation}"></label></div><label class="field"><span>Opacity</span><input data-clip-prop="opacity" type="range" min="0" max="1" step=".05" value="${clip.opacity??1}"></label><label class="field"><span>Blend mode</span><select data-clip-prop="blendMode">${['source-over','screen','multiply','overlay','lighter'].map(x=>`<option ${clip.blendMode===x?'selected':''}>${x}</option>`).join('')}</select></label></div><div class="section"><h3>Crop</h3><div class="two-col"><label class="field"><span>Left %</span><input data-crop="left" type="number" min="0" max="95" value="${Math.round(c.left*100)}"></label><label class="field"><span>Top %</span><input data-crop="top" type="number" min="0" max="95" value="${Math.round(c.top*100)}"></label><label class="field"><span>Right %</span><input data-crop="right" type="number" min="0" max="95" value="${Math.round(c.right*100)}"></label><label class="field"><span>Bottom %</span><input data-crop="bottom" type="number" min="0" max="95" value="${Math.round(c.bottom*100)}"></label></div></div>${objectCommandHtml(clip)}`;return;}
  const c=state.project.composition,st=state.project.lyricStyle;inspector.innerHTML=`<div class="section"><h3>Composition</h3><label class="field"><span>Aspect ratio</span><select data-compose="aspect">${['16:9','9:16','1:1','4:5','21:9'].map(x=>`<option ${c.aspect===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field"><span>Resolution</span><select data-compose="resolution"><option>720p</option><option selected>1080p</option><option>1440p</option><option>4k</option></select></label><label class="field"><span>Frame rate</span><select data-compose="fps">${[24,30,60].map(x=>`<option ${c.fps===x?'selected':''}>${x}</option>`).join('')}</select></label></div><div class="section"><h3>Global lyric style</h3>${textStyleFields(st,'global')}</div>`;}

function renderTimeline(){const zoom=Number($('#timelineZoom').value||1), ppu=pxPerUs(),duration=projectDuration(), width=Math.max(1200,duration*ppu),trackHeight=Number(state.project.workspace?.trackHeight||46);$$('[data-action="timeline-select"],[data-action="timeline-razor"]').forEach(b=>b.classList.toggle('active',b.dataset.action===`timeline-${state.project.workspace?.timelineTool||'select'}`));timelineContent.style.width=`${width}px`;const ruler=$('#ruler');const seconds=duration/1e6;const tickSec=zoom>=3?1:zoom>=1?5:10;let ticks='';for(let s=0;s<=seconds;s+=tickSec)ticks+=`<span class="tick" style="left:${xForUs(s*1e6)}px">${formatClock(s*1e6,false)}</span>`;ruler.innerHTML=ticks;
  const headers=$('#trackHeaders'),tracks=$('#tracks');headers.innerHTML='';tracks.innerHTML='';for(const t of [...state.project.tracks].sort((a,b)=>a.order-b.order)){headers.insertAdjacentHTML('beforeend',`<div class="track-head" style="height:${trackHeight}px" data-track="${t.id}"><button data-track-action="visible" class="${t.visible?'on':''}" title="Visibility">◉</button><button data-track-action="locked" class="${t.locked?'on':''}" title="Lock">⌑</button>${t.type==='audio'?`<button data-track-action="muted" class="${t.muted?'on':''}" title="Mute">M</button>`:''}<span class="name">${esc(t.name)}</span><button data-track-action="up" title="Move layer up">↑</button><button data-track-action="down" title="Move layer down">↓</button></div>`);const row=document.createElement('div');row.className=`track-row ${t.locked?'locked':''}`;row.style.height=`${trackHeight}px`;row.dataset.track=t.id;tracks.append(row);if(t.type==='audio')drawWaveform(row,width);if(t.type==='lyrics'){for(const e of state.project.lyrics)row.append(makeTimelineClip(e,'lyric'));}for(const c of state.project.clips.filter(c=>c.trackId===t.id))row.append(makeTimelineClip(c,c.type));}
  for(const beat of state.project.beats||[]){const d=document.createElement('div');d.className='beat-marker';d.style.left=`${xForUs(typeof beat==='number'?beat:beat.timeUs)}px`;d.style.top='24px';d.style.bottom='0';timelineContent.append(d);}for(const m of state.project.markers||[]){const d=document.createElement('div');d.className='marker-line';d.style.left=`${xForUs(m.timeUs)}px`;d.style.top='24px';d.style.bottom='0';d.title=m.label;timelineContent.append(d);}updatePlayhead();}
function drawWaveform(row,width){if(!runtime.peaks?.length)return;const box=document.createElement('div');box.className='waveform';const frag=document.createDocumentFragment();const step=width/runtime.peaks.length;runtime.peaks.forEach((p,i)=>{const b=document.createElement('i');b.className='wave-bar';b.style.left=`${i*step}px`;const amp=Math.max(Math.abs(p.min),Math.abs(p.max));b.style.height=`${Math.max(1,amp*30)}px`;b.style.transform='translateY(-50%)';frag.append(b);});box.append(frag);row.append(box);}
function makeTimelineClip(o,kind){const d=document.createElement('div');d.className=`clip ${kind} ${(kind==='lyric'?state.selected.lyrics:state.selected.clips).has(o.id)?'selected':''}`;d.dataset.kind=kind==='lyric'?'lyric':'clip';d.dataset.id=o.id;d.style.left=`${xForUs(o.startUs)}px`;d.style.width=`${Math.max(8,xForUs(o.endUs-o.startUs))}px`;d.innerHTML=`<span class="handle left" data-edge="left"></span><span class="label">${esc(kind==='lyric'?o.text:o.content?.text||kind)}</span><span class="handle right" data-edge="right"></span>`;for(const k of o.keyframes||[]){const dot=document.createElement('i');dot.className='key-dot';dot.style.left=`${xForUs(k.timeUs)}px`;d.append(dot);}return d;}
function updatePlayhead(){const x=xForUs(state.playheadUs);$('#playhead').style.left=`${x}px`;const viewLeft=timelineScroll.scrollLeft,viewRight=viewLeft+timelineScroll.clientWidth;if(x<viewLeft||x>viewRight){} }
function updateTime(){const label=`${formatClock(state.playheadUs)} / ${formatClock(projectDuration())}`;$('#timeDisplay').textContent=label;const previewTime=$('#previewTimeDisplay');if(previewTime)previewTime.textContent=label;const seek=$('#previewSeek');if(seek){seek.max=String(projectDuration());seek.value=String(Math.min(projectDuration(),Math.max(0,state.playheadUs)));}}
function syncPlayButtons(){$$('[data-action="play"]').forEach(b=>{if(b.classList.contains('play')||b.classList.contains('preview-play'))b.textContent=audio.playing?'❚❚':'▶';});}


function selectionTransform(clip){if(!clip)return null;if(clip.type==='text'){const style={...state.project.titleStyle,...clip.content?.style};return{x:style.x??.5,y:style.y??.5,scale:style.scale??1,rotation:style.rotation??0,flipX:false,flipY:false};}return{x:clip.transform?.x??.5,y:clip.transform?.y??.5,scale:clip.transform?.scale??1,rotation:clip.transform?.rotation??0,flipX:!!clip.transform?.flipX,flipY:!!clip.transform?.flipY};}
function selectionBoxForClip(clip){const cr=canvas.getBoundingClientRect(),sr=stage.getBoundingClientRect(),t=selectionTransform(clip);if(!t||!cr.width||!cr.height)return null;let w=cr.width*.42*t.scale,h=cr.height*.28*t.scale;if(clip.type==='image'||clip.type==='video'){const el=runtime.assetElements.get(clip.content?.assetId),ew=el?.videoWidth||el?.naturalWidth||el?.width,eh=el?.videoHeight||el?.naturalHeight||el?.height;if(ew&&eh){const crop=normalizeCrop(clip.crop),sw=ew*(1-crop.left-crop.right),sh=eh*(1-crop.top-crop.bottom),base=Math.min(canvas.width/sw,canvas.height/sh);w=(sw*base*t.scale/canvas.width)*cr.width;h=(sh*base*t.scale/canvas.height)*cr.height;}}else if(clip.type==='text'){const style={...state.project.titleStyle,...clip.content?.style};w=cr.width*Math.min(.9,style.maxWidth||.8)*t.scale;h=Math.max(42,(style.fontSize||58)*1.7*(cr.height/canvas.height)*t.scale);}return{x:cr.left-sr.left+t.x*cr.width-w/2,y:cr.top-sr.top+t.y*cr.height-h/2,width:Math.max(36,w),height:Math.max(28,h),rotation:t.rotation};}
function renderSelectionOverlay(){if(!canvasSelection)return;const clip=selectedClip();if(!clip||clip.locked){canvasSelection.classList.remove('active');return;}const box=selectionBoxForClip(clip);if(!box){canvasSelection.classList.remove('active');return;}canvasSelection.classList.add('active');selectionFrame.style.left=`${box.x}px`;selectionFrame.style.top=`${box.y}px`;selectionFrame.style.width=`${box.width}px`;selectionFrame.style.height=`${box.height}px`;selectionFrame.style.transform=`rotate(${box.rotation||0}deg)`;if(selectionToolbar){selectionToolbar.style.left=`${box.x+box.width/2}px`;selectionToolbar.style.top=`${Math.max(48,box.y-8)}px`;const media=clip.type==='image'||clip.type==='video';selectionToolbar.querySelector('[data-selection-action="flip-x"]').hidden=!media;selectionToolbar.querySelector('[data-selection-action="flip-y"]').hidden=!media;selectionToolbar.querySelector('[data-selection-action="crop"]').hidden=!media;}if(cropToolbar)cropToolbar.hidden=!cropMode;}
function mutateSelectedTransform(mutator){const clip=selectedClip();if(!clip||clip.locked)return;const target=state.project.clips.find(c=>c.id===clip.id);if(!target)return;if(target.type==='text'){target.content.style={...(target.content.style||{})};mutator(target.content.style,target);}else{target.transform={...(target.transform||{})};mutator(target.transform,target);}renderFrame();renderSelectionOverlay();}
function commitCurrentGesture(){state.commit(()=>{});renderSelectionOverlay();}
function selectionAction(action){const ids=[...state.selected.clips],clip=selectedClip();if(!clip)return;if(action==='flip-x'||action==='flip-y'){if(!['image','video'].includes(clip.type))return;state.commit(p=>{const c=p.clips.find(x=>x.id===clip.id);c.transform=flipTransform(c.transform,action==='flip-x'?'x':'y');});}else if(action==='duplicate')state.duplicateSelection();else if(action==='group'&&ids.length>1)state.commit(p=>Object.assign(p,groupSelection(p,ids)));else if(action==='group'&&clip.groupId)state.commit(p=>Object.assign(p,ungroupSelection(p,ids)));else if(action==='lock')state.commit(p=>Object.assign(p,setLocked(p,ids,!clip.locked)));else if(action==='crop'&&['image','video'].includes(clip.type)){cropMode={clipId:clip.id,original:structuredClone(clip.crop||{}),draft:normalizeCrop(clip.crop||{})};cropToolbar.hidden=false;toast('Crop mode: drag corner handles, then Apply crop.');}else if(action==='crop-cancel'){if(cropMode){const id=cropMode.clipId,original=cropMode.original;state.project.clips.find(c=>c.id===id).crop=structuredClone(original);cropMode=null;renderFrame();renderSelectionOverlay();}}else if(action==='crop-apply'){if(cropMode){cropMode=null;commitCurrentGesture();}}else if(action==='copy-style'){styleClipboard=copyStyle(state.project,clip.id);toast('Style copied','good');}else if(action==='paste-style'&&styleClipboard)state.commit(p=>Object.assign(p,pasteStyle(p,ids,styleClipboard)));else if(action==='front')state.commit(p=>Object.assign(p,reorderSelection(p,ids,'front')));else if(action==='back')state.commit(p=>Object.assign(p,reorderSelection(p,ids,'back')));else if(action==='forward')state.commit(p=>Object.assign(p,reorderSelection(p,ids,'forward')));else if(action==='backward')state.commit(p=>Object.assign(p,reorderSelection(p,ids,'backward')));else if(action==='reset')state.commit(p=>{const c=p.clips.find(x=>x.id===clip.id);c.transform={...(c.transform||{}),x:.5,y:.5,scale:1,rotation:0,flipX:false,flipY:false};if(c.type==='text')c.content.style={...(c.content.style||{}),x:.5,y:.18,scale:1,rotation:0};});renderSelectionOverlay();}

function renderFrame(){const freq=audio.frequencyData();for(const [id,el] of runtime.assetElements){if(el instanceof HTMLVideoElement){const t=(state.playheadUs/1e6)%(el.duration||1);if(Number.isFinite(t)&&Math.abs((el.currentTime||0)-t)>.25)try{el.currentTime=t;}catch{}}}renderComposition(ctx,state.project,state.playheadUs,{assetElements:runtime.assetElements,frequencyData:freq},{guides:runtime.guides});}
function playbackLoop(){cancelAnimationFrame(renderRAF);const tick=()=>{if(audio.playing){state.playheadUs=Math.min(projectDuration(),audio.currentTimeUs());if(runtime.loopEnabled&&runtime.loopRange&&state.playheadUs>=runtime.loopRange[1]){state.playheadUs=runtime.loopRange[0];audio.seekUs(state.playheadUs);}updatePlayhead();updateTime();renderFrame();if(!runtime.loopEnabled&&state.playheadUs>=projectDuration())audio.stop();}renderRAF=requestAnimationFrame(tick);};tick();}


function currentStylePresetRecord(){return validatePresetRecord({signature:PRESET_SIGNATURE,schemaVersion:PRESET_SCHEMA_VERSION,id:`local-${state.project.id}`,name:`${state.project.name} Style`,author:'Local user',description:'Style exported from the current LyricForge project.',category:'Custom',tags:['custom'],version:'1.0.0',minAppVersion:'0.3.7',accent:state.project.lyricStyle?.activeColor,style:state.project.lyricStyle,background:state.project.background,visualizer:state.project.visualizer,videoEffects:state.project.videoEffects});}
function selectedPortablePreset(){if(presetSelection.kind==='factory'){const p=PRESETS.find(x=>x.id===presetSelection.id);if(p)return factoryPresetToRecord(p);}if(presetSelection.kind==='installed'){const p=installedPresets.find(x=>x.id===presetSelection.id);if(p)return validatePresetRecord(p);}return currentStylePresetRecord();}
async function refreshInstalledPresets(){installedPresets=await listInstalledPresets().catch(()=>[]);if(leftTab==='presets')renderLeft();return installedPresets;}
async function refreshPresetCatalog(){presetCatalogStatus='loading';if(leftTab==='presets')renderLeft();try{const catalog=await fetchPresetCatalog('./presets/catalog.json');presetCatalog=catalog.entries;presetCatalogStatus='ready';}catch(e){console.warn('Preset library unavailable',e);presetCatalogStatus='error';}if(leftTab==='presets')renderLeft();}
async function showPresetImportSummary(record){return await new Promise(resolve=>{modalBody.innerHTML=`<div class="modal-card"><span class="eyebrow">PRESET IMPORT</span><h2>${esc(record.name)}</h2><p>${esc(record.description||'Portable LyricForge preset')}</p><div class="preset-summary"><b>${esc(record.author)}</b><span>${esc(record.category)} · v${esc(record.version)}</span><small>Data-only preset · schema ${record.schemaVersion}</small></div><div class="modal-actions"><button type="button" id="presetCancel">Cancel</button><button type="button" class="primary" id="presetInstall">Install Preset</button></div></div>`;modal.showModal();$('#presetCancel',modalBody).onclick=()=>{modal.close();resolve(false)};$('#presetInstall',modalBody).onclick=()=>{modal.close();resolve(true)};});}
async function importPresetFile(file){if(file.size>PRESET_MAX_BYTES)throw new Error('Preset file is too large.');const record=validatePresetRecord(await file.text());if(!await showPresetImportSummary(record))return null;let replace=false;if(await isPresetInstalled(record.id)){replace=confirm(`${record.name} is already installed. Replace it?`)||'local';}const stored=await installPreset(record,{replace,source:'import'});await refreshInstalledPresets();presetMode='installed';presetSelection={kind:'installed',id:stored.id};renderLeft();toast(`${stored.name} installed`,'good');return stored;}
function choosePresetImport(){const inp=document.createElement('input');inp.type='file';inp.accept='.lyricpreset,application/json';inp.onchange=async()=>{const file=inp.files?.[0];if(!file)return;try{await importPresetFile(file)}catch(e){toast(e.message,'bad')}};inp.click();}
function exportSelectedPreset(){const record=selectedPortablePreset(),name=record.name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'lyricforge-preset';downloadBlob(new Blob([serializePreset(record)],{type:'application/json'}),`${name}.lyricpreset`);toast(`${record.name} exported`,'good');}
async function installCatalogPreset(id){const entry=presetCatalog.find(x=>x.id===id);if(!entry)throw new Error('Preset is no longer in the catalog.');const record=await downloadPreset(entry);const existing=installedPresets.find(x=>x.id===record.id);const stored=await installPreset(record,{replace:!!existing,source:'catalog',sourceUrl:entry.downloadUrl});await refreshInstalledPresets();presetSelection={kind:'installed',id:stored.id};toast(`${stored.name} ${existing?'updated':'installed'}`,'good');}

async function importFiles(files){for(const file of files){try{await importFile(file);}catch(e){console.error(e);toast(`${file.name}: ${e.message}`,'bad');}}}
async function importFile(file){const e=ext(file.name),type=file.type;
  if(e==='lyricpreset'){await importPresetFile(file);return;}
  if(['txt','lrc','srt','vtt','ass','ssa'].includes(e)){const events=parseLyrics(await file.text(),e);state.addLyrics(events);toast(`Imported ${events.length} lyric lines`,'good');leftTab='lyrics';return;}
  if(e==='lyricforge'){const data=await restoreProjectBundle(await file.text(),(id,blob,meta)=>putAsset(id,blob,meta));await loadIntoEditor(data);toast('Portable project bundle imported','good');return;}if(e==='json'){const data=JSON.parse(await file.text());if(data.schemaVersion){await loadIntoEditor(data);toast('Project imported','good');return;}}
  if(['ttf','otf','woff','woff2'].includes(e)||type.startsWith('font/')){const id=uid('font'),family=file.name.replace(/\.[^.]+$/,'');await putAsset(id,file,{name:file.name,type:'font'});const url=URL.createObjectURL(file);const face=new FontFace(family,`url(${url})`);await face.load();document.fonts.add(face);runtime.assetUrls.set(id,url);state.commit(p=>{p.assets.push({id,name:file.name,type:'font',mime:file.type,size:file.size});p.fonts.push({id,family,name:file.name});});toast(`Project font “${family}” added`,'good');return;}
  let assetType=type.startsWith('audio/')?'audio':type.startsWith('image/')?'image':type.startsWith('video/')?'video':null;if(!assetType)throw new Error('Unsupported file type');const id=uid(assetType);await putAsset(id,file,{name:file.name,type:assetType,mime:file.type,size:file.size});const meta={id,name:file.name,type:assetType,mime:file.type,size:file.size,role:null};
  if(assetType==='audio'){runtime.audioBlob=file;const analysis=await audio.load(file);runtime.peaks=analysis.peaks;runtime.bpm=analysis.beat.bpm;state.commit(p=>{p.assets=p.assets.filter(a=>a.id!==id);meta.role='master-audio';p.assets.push(meta);p.audioMasterAssetId=id;p.durationUs=analysis.durationUs;p.beats=analysis.beat.beatsUs;});toast(`Audio ready · ${analysis.beat.bpm||'—'} BPM`,'good');}
  else{const url=URL.createObjectURL(file);runtime.assetUrls.set(id,url);let el;if(assetType==='image'){el=new Image();el.src=url;await el.decode();}else{el=document.createElement('video');el.src=url;el.muted=true;el.loop=true;el.playsInline=true;await new Promise((res,rej)=>{el.onloadedmetadata=res;el.onerror=()=>rej(new Error('Video could not be decoded by this browser.'));});}runtime.assetElements.set(id,el);state.commit(p=>{if(!p.assets.some(a=>a.id===id)){meta.role=p.assets.some(a=>a.role==='background')?null:'background';p.assets.push(meta);}if(meta.role==='background')p.background.type=assetType;});toast(`${assetType} imported`,'good');}
}
async function restoreAssets(){for(const url of runtime.assetUrls.values())URL.revokeObjectURL(url);runtime.assetUrls.clear();runtime.assetElements.clear();runtime.audioBlob=null;runtime.peaks=[];for(const a of state.project.assets){const rec=await getAsset(a.id).catch(()=>null);if(!rec?.blob)continue;const blob=rec.blob;if(a.type==='audio'&&a.id===state.project.audioMasterAssetId){runtime.audioBlob=blob;try{const analysis=await audio.load(blob);runtime.peaks=analysis.peaks;runtime.bpm=analysis.beat.bpm;}catch{}}else if(a.type==='image'){const u=URL.createObjectURL(blob);runtime.assetUrls.set(a.id,u);const im=new Image();im.src=u;try{await im.decode();runtime.assetElements.set(a.id,im);}catch{}}else if(a.type==='video'){const u=URL.createObjectURL(blob);runtime.assetUrls.set(a.id,u);const v=document.createElement('video');v.src=u;v.muted=true;v.loop=true;v.playsInline=true;await new Promise(r=>{v.onloadedmetadata=r;v.onerror=r;});runtime.assetElements.set(a.id,v);}else if(a.type==='font'){const family=state.project.fonts.find(f=>f.id===a.id)?.family||a.name.replace(/\.[^.]+$/,'');const u=URL.createObjectURL(blob);runtime.assetUrls.set(a.id,u);try{const face=new FontFace(family,`url(${u})`);await face.load();document.fonts.add(face);}catch{}}}renderFrame();renderTimeline();}
async function loadIntoEditor(project){audio.stop();state.replace(normalizeProject(project),{dirty:false});await restoreAssets();loadWebFontsForProject();}

function setDeep(obj,path,value){const parts=path.split('.');let cur=obj;for(let i=0;i<parts.length-1;i++){const k=parts[i];if(!cur[k]||typeof cur[k]!=='object')cur[k]={};cur=cur[k];}cur[parts.at(-1)]=value;}
function typedValue(input){if(input.type==='checkbox')return input.checked;if(input.type==='number'||input.type==='range')return Number(input.value);return input.value;}

left.addEventListener('click',async e=>{const b=e.target.closest('[data-left]');if(b){const a=b.dataset.left;if(a==='import')$('#fileInput').click();if(a==='import-project'){const inp=document.createElement('input');inp.type='file';inp.accept='.lyricforge,.json';inp.onchange=()=>importFiles(inp.files);inp.click();}if(a==='export-project'){const bundle=await createProjectBundle(state.project,getAsset);downloadBlob(bundle,`${state.project.name}.lyricforge`);}if(a==='add-pasted'){const text=$('#lyricPaste')?.value||'';if(text.trim())state.addLyrics(parseLyrics(text,'txt'));}if(a==='add-line')state.addLyric();if(a==='auto-detect')showTranscriptionModal();if(a==='add-title')state.addTextClip('Song Title');if(a==='marker')state.addMarker();if(a==='set-start'){const l=selectedLyric();if(l)state.updateLyric(l.id,{startUs:state.playheadUs});}if(a==='set-end'){const l=selectedLyric();if(l)state.updateLyric(l.id,{endUs:Math.max(l.startUs+10_000,state.playheadUs)});}if(a==='snap-playhead'){const l=selectedLyric();if(l)state.updateLyric(l.id,{startUs:state.playheadUs});}if(a==='nudge-earlier')state.nudgeSelected(-Number($('#nudgeAmount').value||50000));if(a==='nudge-later')state.nudgeSelected(Number($('#nudgeAmount').value||50000));if(a==='merge')state.mergeSelected();if(a==='prev-line'||a==='next-line'){const sorted=[...state.project.lyrics].sort((x,y)=>x.startUs-y.startUs),cur=selectedLyric(),i=Math.max(0,sorted.findIndex(x=>x.id===cur?.id)),n=a==='prev-line'?Math.max(0,i-1):Math.min(sorted.length-1,i+1);if(sorted[n])state.selectLyric(sorted[n].id);}if(a==='tap-sync')manualTapSync();if(a==='save-preset'){const name=prompt('Preset name','My LyricForge Style');if(name)state.commit(p=>p.customPresets.push({name,lyricStyle:structuredClone(p.lyricStyle),background:structuredClone(p.background),visualizer:structuredClone(p.visualizer),videoEffects:structuredClone(normalizeVideoEffects(p.videoEffects))}));}if(a==='reset-effects')state.commit(p=>{p.videoEffects=normalizeVideoEffects();});if(a==='add-media-layer'){const id=b.dataset.id,asset=state.project.assets.find(x=>x.id===id);if(asset){const track=state.project.tracks.find(t=>t.type===(asset.type==='image'?'images':'overlays'))||state.project.tracks.find(t=>t.type==='overlays');const clip=createClip(asset.type,track.id,state.playheadUs,Math.min(projectDuration(),state.playheadUs+5_000_000),{assetId:id});state.commit(p=>p.clips.push(clip));state.selectClip(clip.id);}}if(a==='set-background'){const id=b.dataset.id;state.commit(p=>{p.assets.forEach(x=>{if(x.role==='background')x.role=null;});const asset=p.assets.find(x=>x.id===id);if(asset){asset.role='background';p.background.type=asset.type;}});}if(a==='low-confidence'){searchLyrics='';renderLeft();$$('.lyric-row',left).forEach(r=>{const id=r.dataset.lyricId,e=state.project.lyrics.find(x=>x.id===id);r.classList.toggle('hidden',(e?.confidence??1)>=.75);});}}const textEffect=e.target.closest('[data-text-effect]');if(textEffect){const c=selectedClip();if(c?.type==='text')state.commit(p=>{const x=p.clips.find(z=>z.id===c.id);x.content.style=x.content.style||{};x.content.style.entrance={...(p.titleStyle.entrance||{}),...(x.content.style.entrance||{}),name:textEffect.dataset.textEffect};});else state.commit(p=>{p.lyricStyle.entrance={...p.lyricStyle.entrance,name:textEffect.dataset.textEffect};});toast(`${textEffect.textContent.trim()} applied`,'good');}const row=e.target.closest('[data-lyric-id]');if(row&&!e.target.matches('input'))state.selectLyric(row.dataset.lyricId,e.ctrlKey||e.metaKey);const preset=e.target.closest('[data-preset]');if(preset){const chosen=PRESETS.find(p=>p.id===preset.dataset.preset);state.commit(p=>{const n=applyPreset(p,preset.dataset.preset);Object.assign(p,n);});if(chosen?.fontFamily)ensureWebFont(chosen.fontFamily).then(renderFrame).catch(()=>{});toast(`${chosen?.name} preset applied`,'good');}const cp=e.target.closest('[data-custom-preset]');if(cp){const p=state.project.customPresets[Number(cp.dataset.customPreset)];if(p){state.commit(x=>{x.lyricStyle=structuredClone(p.lyricStyle);x.background=structuredClone(p.background);x.visualizer=structuredClone(p.visualizer);x.videoEffects=structuredClone(normalizeVideoEffects(p.videoEffects));});ensureWebFont(p.lyricStyle?.fontFamily).then(renderFrame).catch(()=>{});}}});
left.addEventListener('click',async e=>{
  const mode=e.target.closest('[data-left="preset-mode"]');if(mode){presetMode=mode.dataset.mode;renderLeft();if(presetMode==='installed')await refreshInstalledPresets();if(presetMode==='library'&&(presetCatalogStatus==='idle'||presetCatalogStatus==='error'))await refreshPresetCatalog();return;}
  const imp=e.target.closest('[data-left="import-preset"]');if(imp){choosePresetImport();return;}
  const exp=e.target.closest('[data-left="export-preset"]');if(exp){exportSelectedPreset();return;}
  const ref=e.target.closest('[data-left="refresh-installed"]');if(ref){await refreshInstalledPresets();return;}
  const lib=e.target.closest('[data-left="refresh-library"]');if(lib){await refreshPresetCatalog();return;}
  const install=e.target.closest('[data-left="install-library"]');if(install){install.disabled=true;try{await installCatalogPreset(install.dataset.id)}catch(err){toast(err.message,'bad')}finally{install.disabled=false}return;}
  const remove=e.target.closest('[data-left="remove-installed"]');if(remove){const item=installedPresets.find(x=>x.id===remove.dataset.id);if(item&&confirm(`Remove ${item.name}? Existing projects keep their applied style.`)){await removeInstalledPreset(item.id);await refreshInstalledPresets();toast(`${item.name} removed`,'good')}return;}
  const installed=e.target.closest('[data-installed-preset]');if(installed){const record=installedPresets.find(x=>x.id===installed.dataset.installedPreset);if(record){presetSelection={kind:'installed',id:record.id};state.commit(p=>Object.assign(p,applyPresetRecord(p,record)));ensureWebFont(record.style?.fontFamily).then(renderFrame).catch(()=>{});toast(`${record.name} preset applied`,'good');}return;}
  const factory=e.target.closest('[data-preset]');if(factory){presetSelection={kind:'factory',id:factory.dataset.preset};}
});
left.addEventListener('input',e=>{if(e.target.id==='presetLibrarySearch'){presetQuery=e.target.value;renderLeft();}});
left.addEventListener('change',e=>{if(e.target.id==='presetLibraryCategory'){presetCategory=e.target.value;renderLeft();}});
left.addEventListener('change',e=>{if(e.target.matches('[data-line-text]'))state.updateLyric(e.target.dataset.lineText,{text:e.target.value});if(e.target.id==='lyricSearch'){searchLyrics=e.target.value;renderLeft();}const path=e.target.dataset.project;if(path)state.commit(p=>setDeep(p,path,typedValue(e.target)));const style=e.target.dataset.style;if(style)applyStyleChange(style,typedValue(e.target));});
left.addEventListener('input',e=>{if(e.target.dataset.project&&e.target.type==='range')state.commit(p=>setDeep(p,e.target.dataset.project,typedValue(e.target)),{history:false});});

inspector.addEventListener('change',e=>{const l=selectedLyric(),c=selectedClip(),k=e.target.dataset.inspect;if(k&&l){if(k==='lyric.text')state.updateLyric(l.id,{text:e.target.value});if(k==='lyric.start')state.updateLyric(l.id,{startUs:msToUs(e.target.value)});if(k==='lyric.end')state.updateLyric(l.id,{endUs:msToUs(e.target.value)});if(k==='lyric.section')state.updateLyric(l.id,{sectionType:e.target.value});}if(k&&c){if(k==='clip.text')state.commit(p=>{p.clips.find(x=>x.id===c.id).content.text=e.target.value;});if(k==='clip.start')state.commit(p=>{p.clips.find(x=>x.id===c.id).startUs=msToUs(e.target.value);});if(k==='clip.end')state.commit(p=>{p.clips.find(x=>x.id===c.id).endUs=msToUs(e.target.value);});}if(e.target.dataset.word&&l){const [wid,prop]=e.target.dataset.word.split(':');state.commit(p=>{const w=p.lyrics.find(x=>x.id===l.id)?.words.find(x=>x.id===wid);if(w)w[prop==='text'?'text':prop==='start'?'startUs':'endUs']=prop==='text'?e.target.value:msToUs(e.target.value);});}if(e.target.dataset.style)applyStyleChange(e.target.dataset.style,typedValue(e.target));if(e.target.dataset.clipTransform&&c){state.commit(p=>{p.clips.find(x=>x.id===c.id).transform[e.target.dataset.clipTransform]=Number(e.target.value);});}if(e.target.dataset.clipProp&&c){state.commit(p=>{p.clips.find(x=>x.id===c.id)[e.target.dataset.clipProp]=typedValue(e.target);});}if(e.target.dataset.compose){if(e.target.dataset.compose==='aspect'){const res=resolveResolution('1080p',e.target.value);state.commit(p=>{p.composition.aspect=e.target.value;p.composition.width=res.width;p.composition.height=res.height;});}if(e.target.dataset.compose==='resolution'){const res=resolveResolution(e.target.value,state.project.composition.aspect);state.commit(p=>{p.composition.width=res.width;p.composition.height=res.height;});}if(e.target.dataset.compose==='fps')state.commit(p=>p.composition.fps=Number(e.target.value));}});
inspector.addEventListener('change',e=>{const c=selectedClip();if(!c)return;const meta=e.target.dataset.clipMeta;if(meta==='label')state.commit(p=>Object.assign(p,setClipLabel(p,c.id,e.target.value)));if(meta==='fadeIn'||meta==='fadeOut'){const a=meta==='fadeIn'?msToUs(e.target.value):c.fadeInUs,b=meta==='fadeOut'?msToUs(e.target.value):c.fadeOutUs;state.commit(p=>Object.assign(p,setClipFade(p,c.id,{fadeInUs:a,fadeOutUs:b})));}if(e.target.dataset.crop){const key=e.target.dataset.crop;state.commit(p=>{const x=p.clips.find(z=>z.id===c.id),crop={...(x.crop||{})};crop[key]=Number(e.target.value)/100;x.crop=normalizeCrop(crop);});}});
inspector.addEventListener('click',e=>{const a=e.target.dataset.inspectAction;if(!a)return;if(a==='split'){const c=selectedClip();if(c){try{state.commit(p=>Object.assign(p,splitClip(p,c.id,state.playheadUs)));}catch(err){toast(err.message,'bad')}}else state.splitSelected();return;}if(a==='delete'){state.deleteSelection();return;}if(a==='use-global'){const l=selectedLyric();if(l)state.updateLyric(l.id,{styleOverride:null});return;}if(a==='add-keyframe'){const c=selectedClip();if(c){const local=Math.max(0,state.playheadUs-c.startUs),value=c.opacity??1;try{state.commit(p=>Object.assign(p,toggleKeyframeAt(p,c.id,'opacity',local,value)));}catch(err){toast(err.message,'bad')}}return;}if(['flip-x','flip-y','duplicate','front','forward','backward','back','group','lock','copy-style','paste-style','reset','crop'].includes(a)){selectionAction(a);return;}});
function applyStyleChange(key,value){const [scope,...rest]=key.split(':');const path=rest.join(':');if(scope==='global')state.commit(p=>setDeep(p.lyricStyle,path,value));else if(scope==='clip'){const c=selectedClip();if(!c||c.type!=='text')return;state.commit(p=>{const x=p.clips.find(z=>z.id===c.id);x.content.style=x.content.style||{};setDeep(x.content.style,path,value);});}if(path==='fontFamily')ensureWebFont(value).then(renderFrame).catch(()=>{});}

function manualTapSync(){const sorted=[...state.project.lyrics].sort((a,b)=>a.startUs-b.startUs);if(!sorted.length)return;const cur=selectedLyric();let i=cur?sorted.findIndex(x=>x.id===cur.id):tapSyncIndex;if(i<0)i=0;const result=tapSync(sorted,i,state.playheadUs,true);state.commit(p=>{const map=new Map(result.events.map(x=>[x.id,x]));p.lyrics=p.lyrics.map(x=>map.get(x.id)||x);});tapSyncIndex=result.nextIndex;const next=result.events[result.nextIndex];if(next)state.selectLyric(next.id);}


function showTimelineContext(x=innerWidth/2,y=innerHeight/2){if(!timelineContextSheet)return;timelineContextSheet.hidden=false;timelineContextSheet.style.left=`${Math.max(8,Math.min(innerWidth-340,x))}px`;timelineContextSheet.style.top=`${Math.max(8,Math.min(innerHeight-80,y))}px`;}
function hideTimelineContext(){if(timelineContextSheet)timelineContextSheet.hidden=true;}
let longPressTimer=null,longPressStart=null;
$('#tracks').addEventListener('contextmenu',e=>{const clip=e.target.closest('.clip');if(!clip)return;e.preventDefault();if(clip.dataset.kind==='lyric')state.selectLyric(clip.dataset.id);else state.selectClip(clip.dataset.id);showTimelineContext(e.clientX,e.clientY);});
$('#tracks').addEventListener('pointerdown',e=>{const clip=e.target.closest('.clip');if(!clip||e.pointerType==='mouse')return;clearTimeout(longPressTimer);longPressStart={x:e.clientX,y:e.clientY};longPressTimer=setTimeout(()=>{if(clip.dataset.kind==='lyric')state.selectLyric(clip.dataset.id);else state.selectClip(clip.dataset.id);showTimelineContext(e.clientX,e.clientY);longPressTimer=null;},520);});
$('#tracks').addEventListener('pointermove',e=>{if(longPressTimer&&longPressStart&&Math.hypot(e.clientX-longPressStart.x,e.clientY-longPressStart.y)>10){clearTimeout(longPressTimer);longPressTimer=null;}});
window.addEventListener('pointerup',()=>{if(longPressTimer){clearTimeout(longPressTimer);longPressTimer=null;}});
timelineContextSheet?.addEventListener('click',e=>{const b=e.target.closest('[data-context-action]');if(!b)return;const action=b.dataset.contextAction;hideTimelineContext();if(action!=='close')topAction(action);});
function handleTrackHeaderClick(e){const b=e.target.closest('[data-track-action]');if(!b)return;const head=e.target.closest('[data-track]'),id=head.dataset.track,a=b.dataset.trackAction;state.commit(p=>{const t=p.tracks.find(x=>x.id===id);if(!t)return;if(['visible','locked','muted'].includes(a))t[a]=!t[a];else{const sorted=[...p.tracks].sort((x,y)=>x.order-y.order),i=sorted.findIndex(x=>x.id===id),j=a==='up'?Math.max(0,i-1):Math.min(sorted.length-1,i+1);if(i!==j){[sorted[i].order,sorted[j].order]=[sorted[j].order,sorted[i].order];}}});}
$('#trackHeaders').addEventListener('click',handleTrackHeaderClick);
$('#tracks').addEventListener('pointerdown',e=>{const clip=e.target.closest('.clip');if(clip){const kind=clip.dataset.kind,id=clip.dataset.id,append=e.ctrlKey||e.metaKey;const obj0=kind==='lyric'?state.project.lyrics.find(x=>x.id===id):state.project.clips.find(x=>x.id===id),track0=kind==='lyric'?state.project.tracks.find(t=>t.type==='lyrics'):state.project.tracks.find(t=>t.id===obj0?.trackId);if(obj0?.locked||track0?.locked){toast('Clip or track is locked.');e.preventDefault();return;}if(kind!=='lyric'&&state.project.workspace?.timelineTool==='razor'){const rect=timelineContent.getBoundingClientRect(),time=usForX(e.clientX-rect.left+timelineScroll.scrollLeft);try{const next=splitClip(state.project,id,time);state.commit(p=>Object.assign(p,next));toast('Clip split','good');}catch(err){toast(err.message,'bad')}e.preventDefault();return;}if(kind==='lyric')state.selectLyric(id,append);else state.selectClip(id,append);const obj=kind==='lyric'?state.project.lyrics.find(x=>x.id===id):state.project.clips.find(x=>x.id===id);const edge=e.target.dataset.edge||'move';dragState={kind,id,edge,startX:e.clientX,startUs:obj.startUs,endUs:obj.endUs,node:clip};clip.setPointerCapture?.(e.pointerId);e.preventDefault();return;}const row=e.target.closest('.track-row');if(!row)return;if(e.shiftKey){const rect=timelineContent.getBoundingClientRect();boxState={x0:e.clientX-rect.left+timelineScroll.scrollLeft,y0:e.clientY-rect.top+timelineScroll.scrollTop};const box=$('#selectionBox');box.style.display='block';box.style.left=`${boxState.x0}px`;box.style.top=`${boxState.y0}px`;box.style.width='0';box.style.height='0';}else{const rect=timelineContent.getBoundingClientRect();state.setPlayhead(usForX(e.clientX-rect.left+timelineScroll.scrollLeft));audio.seekUs(state.playheadUs);}});
window.addEventListener('pointermove',e=>{if(dragState){const dx=e.clientX-dragState.startX,du=Math.round(dx/pxPerUs());let start=dragState.startUs,end=dragState.endUs;if(dragState.edge==='left')start=Math.min(end-10_000,Math.max(0,start+du));else if(dragState.edge==='right')end=Math.max(start+10_000,end+du);else{start=Math.max(0,start+du);end=start+(dragState.endUs-dragState.startUs);}dragState.preview={start,end};dragState.node.style.left=`${xForUs(start)}px`;dragState.node.style.width=`${Math.max(8,xForUs(end-start))}px`;}if(boxState){const rect=timelineContent.getBoundingClientRect(),x=e.clientX-rect.left+timelineScroll.scrollLeft,y=e.clientY-rect.top+timelineScroll.scrollTop,box=$('#selectionBox');box.style.left=`${Math.min(x,boxState.x0)}px`;box.style.top=`${Math.min(y,boxState.y0)}px`;box.style.width=`${Math.abs(x-boxState.x0)}px`;box.style.height=`${Math.abs(y-boxState.y0)}px`;boxState.x=x;boxState.y=y;}});
window.addEventListener('pointerup',()=>{if(dragState){let {start,end}=dragState.preview||{start:dragState.startUs,end:dragState.endUs};if($('#snapToggle').checked){const s=snapTimeUs(start,{thresholdUs:80_000,playheadUs:state.playheadUs,beats:state.project.beats,markers:state.project.markers,lyrics:state.project.lyrics.filter(x=>x.id!==dragState.id),clips:state.project.clips.filter(x=>x.id!==dragState.id)});const delta=s.timeUs-start;if(s.source){start+=delta;if(dragState.edge==='move')end+=delta;}}if(dragState.kind==='lyric')state.updateLyric(dragState.id,{startUs:start,endUs:end});else if(dragState.edge==='left'||dragState.edge==='right'){try{state.commit(p=>Object.assign(p,trimClip(p,dragState.id,{startUs:start,endUs:end})));}catch(err){toast(err.message,'bad')}}else state.commit(p=>{const c=p.clips.find(x=>x.id===dragState.id);c.startUs=start;c.endUs=end;});dragState=null;}if(boxState){const box=$('#selectionBox'),br=box.getBoundingClientRect();state.selected.lyrics.clear();state.selected.clips.clear();for(const el of $$('.clip')){const r=el.getBoundingClientRect();if(r.right>=br.left&&r.left<=br.right&&r.bottom>=br.top&&r.top<=br.bottom){(el.dataset.kind==='lyric'?state.selected.lyrics:state.selected.clips).add(el.dataset.id);}}box.style.display='none';boxState=null;state.emit('selection');}});


let previewPinching=false,previewPinchState=null;
function setPreviewZoom(value){runtime.previewZoom=Math.max(.6,Math.min(3,value));canvas.style.transform=`scale(${runtime.previewZoom})`;canvas.style.transformOrigin='center center';return runtime.previewZoom;}
function currentScaleTarget(){
  const clip=selectedClip(),lyric=selectedLyric();
  if(clip){if(clip.type==='text')return {kind:'text',id:clip.id,scale:clip.content?.style?.scale??state.project.titleStyle.scale??1};return {kind:'media',id:clip.id,scale:clip.transform?.scale??1};}
  if(lyric)return {kind:'lyric',id:lyric.id,scale:lyric.styleOverride?.scale??state.project.lyricStyle.scale??1};
  return null;
}
function writeScale(target,value,project=state.project){
  if(!target)return;
  if(target.kind==='text'){const c=project.clips.find(x=>x.id===target.id);if(c){c.content.style={...(c.content.style||{}),scale:value};}}
  else if(target.kind==='media'){const c=project.clips.find(x=>x.id===target.id);if(c)c.transform={...(c.transform||{}),scale:value};}
  else if(target.kind==='lyric'){const l=project.lyrics.find(x=>x.id===target.id);if(l)l.styleOverride={...(l.styleOverride||{}),scale:value};}
}
function applyPreviewPinch({startDistance=100,currentDistance=100,startScale=null}={}){
  const target=currentScaleTarget();
  if(target){const value=pinchValue(startScale??target.scale,startDistance,currentDistance,.2,5);state.commit(p=>writeScale(target,value,p));return value;}
  const value=pinchValue(startScale??runtime.previewZoom,startDistance,currentDistance,.6,3);setPreviewZoom(value);return value;
}
stage.addEventListener('touchstart',e=>{if(e.touches.length!==2)return;previewPinching=true;e.preventDefault();const target=currentScaleTarget();previewPinchState={distance:touchDistance(e.touches),target,startScale:target?.scale??runtime.previewZoom,final:null};},{passive:false});
stage.addEventListener('touchmove',e=>{if(!previewPinching||e.touches.length!==2||!previewPinchState)return;e.preventDefault();const d=touchDistance(e.touches);const value=pinchValue(previewPinchState.startScale,previewPinchState.distance,d,previewPinchState.target?.kind ? .2 : .6,previewPinchState.target?5:3);previewPinchState.final=value;if(previewPinchState.target){writeScale(previewPinchState.target,value);renderFrame();}else setPreviewZoom(value);},{passive:false});
stage.addEventListener('touchend',e=>{if(!previewPinching)return;if(e.touches.length>=2)return;const ps=previewPinchState;previewPinching=false;previewPinchState=null;if(ps?.target&&ps.final!=null)state.commit(()=>{});},{passive:true});

canvasSelection?.addEventListener('click',e=>{const b=e.target.closest('[data-selection-action]');if(b){e.preventDefault();e.stopPropagation();selectionAction(b.dataset.selectionAction);}});
canvasSelection?.addEventListener('pointerdown',e=>{
  const clip=selectedClip();if(!clip||clip.locked)return;const handle=e.target.closest('[data-canvas-handle]')?.dataset.canvasHandle||(!e.target.closest('.selection-toolbar')&&e.target.closest('#selectionFrame')?'move':null);if(!handle)return;e.preventDefault();e.stopPropagation();const startBox=selectionBoxForClip(clip),start={x:e.clientX,y:e.clientY},startTransform=selectionTransform(clip),frameRect=selectionFrame.getBoundingClientRect(),center={x:frameRect.left+frameRect.width/2,y:frameRect.top+frameRect.height/2},startAngle=Math.atan2(e.clientY-center.y,e.clientX-center.x)*180/Math.PI;let changed=false;
  const move=ev=>{const dx=ev.clientX-start.x,dy=ev.clientY-start.y;changed=true;if(cropMode&&handle!=='move'&&handle!=='rotate'){const names={nw:'left top',ne:'right top',sw:'left bottom',se:'right bottom'};const c=state.project.clips.find(x=>x.id===clip.id);cropMode.draft=applyCropDrag(cropMode.original,names[handle]||handle,{x:dx/Math.max(1,startBox.width),y:dy/Math.max(1,startBox.height)});c.crop=structuredClone(cropMode.draft);renderFrame();renderSelectionOverlay();return;}if(handle==='rotate'){const rot=rotateFromPointer(center,{x:ev.clientX,y:ev.clientY},{startAngleDeg:startAngle,startRotationDeg:startTransform.rotation});mutateSelectedTransform(t=>{t.rotation=rot});return;}if(handle==='move'){const cr=canvas.getBoundingClientRect(),nx=Math.max(0,Math.min(1,startTransform.x+dx/cr.width)),ny=Math.max(0,Math.min(1,startTransform.y+dy/cr.height));mutateSelectedTransform(t=>{t.x=Math.abs(nx-.5)<8/cr.width?.5:nx;t.y=Math.abs(ny-.5)<8/cr.height?.5:ny});alignmentGuides.classList.toggle('show-y',Math.abs(nx-.5)<8/cr.width);alignmentGuides.classList.toggle('show-x',Math.abs(ny-.5)<8/cr.height);return;}const next=resizeFromHandle(startBox,handle,{x:dx,y:dy},{aspectLocked:true,minSize:24});const ratio=next.width/Math.max(1,startBox.width);mutateSelectedTransform(t=>{t.scale=Math.max(.05,Math.min(20,startTransform.scale*ratio));});};
  const up=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);alignmentGuides.classList.remove('show-x','show-y');if(changed&&!cropMode)commitCurrentGesture();};window.addEventListener('pointermove',move);window.addEventListener('pointerup',up,{once:true});
});
canvas.addEventListener('pointerdown',e=>{const clip=selectedClip(),lyric=selectedLyric();if(!clip&&!lyric)return;const rect=canvas.getBoundingClientRect(),start={x:e.clientX,y:e.clientY};const origin=clip?(clip.type==='text'?{x:(clip.content?.style?.x??state.project.titleStyle.x),y:(clip.content?.style?.y??state.project.titleStyle.y)}:{x:clip.transform?.x??.5,y:clip.transform?.y??.5}):{x:state.project.lyricStyle.x,y:state.project.lyricStyle.y};const move=ev=>{if(previewPinching)return;const nx=Math.max(0,Math.min(1,origin.x+(ev.clientX-start.x)/rect.width)),ny=Math.max(0,Math.min(1,origin.y+(ev.clientY-start.y)/rect.height));if(clip){const c=state.project.clips.find(x=>x.id===clip.id);if(c.type==='text')c.content.style={...(c.content.style||{}),x:nx,y:ny};else c.transform={...(c.transform||{}),x:nx,y:ny};}else{state.project.lyricStyle.x=nx;state.project.lyricStyle.y=ny;}renderFrame();renderSelectionOverlay();};const up=ev=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);if(previewPinching)return;const nx=Math.max(0,Math.min(1,origin.x+(ev.clientX-start.x)/rect.width)),ny=Math.max(0,Math.min(1,origin.y+(ev.clientY-start.y)/rect.height));if(clip)state.commit(p=>{const c=p.clips.find(x=>x.id===clip.id);if(c.type==='text')c.content.style={...(c.content.style||{}),x:nx,y:ny};else c.transform={...(c.transform||{}),x:nx,y:ny};});else state.commit(p=>{p.lyricStyle.x=nx;p.lyricStyle.y=ny;});};window.addEventListener('pointermove',move);window.addEventListener('pointerup',up);});

async function showOpenModal(){const ps=await listProjects();modalBody.innerHTML=`<div class="modal-card"><h2>Open Project</h2><p class="subtle">Projects and media stay in this browser's local storage.</p>${ps.map(p=>`<div class="project-row"><div><b>${esc(p.name)}</b><div class="subtle">${new Date(p.modifiedAt).toLocaleString()} · ${p.lyrics.length} lyric lines</div></div><button type="button" data-open-project="${p.id}">Open</button></div>`).join('')||'<p>No saved projects yet.</p>'}<div class="modal-actions"><button value="cancel">Close</button></div></div>`;modal.showModal();}
modalBody.addEventListener('click',async e=>{const id=e.target.dataset.openProject;if(id){const p=await loadProject(id);if(p){modal.close();await loadIntoEditor(p);toast('Project opened','good');}}});

function showNewModal(){modalBody.innerHTML=`<div class="modal-card"><h2>New Lyric Video</h2><label class="field"><span>Project name</span><input id="newName" value="Untitled Lyric Video"></label><div class="two-col"><label class="field"><span>Aspect</span><select id="newAspect"><option>16:9</option><option>9:16</option><option>1:1</option><option>4:5</option><option>21:9</option></select></label><label class="field"><span>Resolution</span><select id="newRes"><option>720p</option><option selected>1080p</option><option>1440p</option><option>4k</option></select></label></div><div class="modal-actions"><button value="cancel">Cancel</button><button type="button" class="primary" id="createProject">Create</button></div></div>`;modal.showModal();$('#createProject',modalBody).onclick=()=>{const p=createProject($('#newName').value||'Untitled Lyric Video'),aspect=$('#newAspect').value,res=$('#newRes').value,r=resolveResolution(res,aspect);p.composition.aspect=aspect;p.composition.width=r.width;p.composition.height=r.height;modal.close();state.replace(p,{dirty:true});restoreAssets();};}

function showTranscriptionModal(){
  const hasAudio=!!runtime.audioBlob,support=browserWhisperSupport();
  modalBody.innerHTML=`<div class="modal-card transcription-modal">
    <div class="modal-hero"><div class="modal-icon ai-glow">✦</div><div><span class="eyebrow">BUILT-IN AI</span><h2>Auto Detect Lyrics</h2><p>Turn the imported song into editable lyrics with line and word timing.</p></div><span class="privacy-badge large">● Runs on this device</span></div>
    <div class="tx-provider-card selected"><div><b>Built-in Whisper</b><small>No endpoint, API key, account, or upload required.</small></div><span class="recommended">Recommended</span></div>
    <div class="tx-grid"><label class="field"><span>Language</span><select id="txLanguage"><option value="auto" selected>Auto detect</option><option value="en">English</option><option value="fr">French</option><option value="es">Spanish</option><option value="de">German</option><option value="it">Italian</option><option value="pt">Portuguese</option></select></label><label class="field"><span>Quality</span><select id="txQuality"><option value="fast" selected>Fast · smaller model</option><option value="balanced">Balanced · larger model</option><option value="accurate">Accurate · large model</option></select></label></div>
    <div class="tx-notice"><span>↓</span><div><b>Download once</b><small>The AI model downloads the first time you use it and is cached by your browser. Audio stays on this device in built-in mode.</small></div></div>
    ${!hasAudio?'<div class="callout warning"><b>Add a song first</b><span>Import an audio file before running automatic transcription.</span></div>':''}
    <details class="advanced-provider"><summary>Advanced providers</summary><div class="advanced-provider-body"><label class="field"><span>Provider</span><select id="txMode"><option value="builtin" selected>Built-in Whisper (no setup)</option><option value="local">Local Timing Assist (uses pasted lyrics)</option><option value="remote">Whisper-compatible API</option></select></label><div id="txLocal" class="hidden"><label class="field"><span>Lyrics draft</span><textarea id="txDraft" placeholder="Paste lyrics to distribute across the song…">${esc(state.project.lyrics.map(e=>e.text).join('\n'))}</textarea></label></div><div id="txRemote" class="hidden"><label class="field"><span>Endpoint</span><input id="txEndpoint" type="url" placeholder="https://…/audio/transcriptions"></label><label class="field"><span>API key (not saved)</span><input id="txKey" type="password"></label><label class="consent-row"><input type="checkbox" id="txConsent"><span>I understand remote mode uploads my audio to the endpoint above.</span></label></div></div></details>
    <div id="txStatus" class="tx-status hidden"><div class="tx-status-head"><div><span class="status-dot"></span><b id="txMessage">Preparing…</b></div><span id="txPercent">0%</span></div><div class="progress premium"><i id="txBar"></i></div><div class="tx-phase-row"><span data-phase="audio">Audio</span><span data-phase="model">Model</span><span data-phase="transcribe">Listen</span><span data-phase="structure">Structure</span></div><pre id="txPartial"></pre></div>
    <div class="modal-actions"><button type="button" id="txCancel">Cancel</button><button type="button" class="primary hero-action" id="txRun" ${hasAudio?'':'disabled'}><span>✦</span> Transcribe Song</button></div>
  </div>`;
  modal.showModal();
  let controller=null;
  const modeEl=$('#txMode');
  const updateMode=()=>{const mode=modeEl.value;$('#txLocal').classList.toggle('hidden',mode!=='local');$('#txRemote').classList.toggle('hidden',mode!=='remote');const run=$('#txRun');run.disabled=(mode!=='local'&&!runtime.audioBlob);run.innerHTML=mode==='builtin'?'<span>✦</span> Transcribe Song':mode==='local'?'Create Timing Guide':'Use Remote Provider';};
  modeEl.onchange=updateMode;updateMode();
  $('#txCancel').onclick=()=>{controller?.abort();modal.close();};
  const setProgress=(p={})=>{const value=Math.max(0,Math.min(1,Number(p.progress)||0));$('#txStatus').classList.remove('hidden');$('#txBar').style.width=`${Math.round(value*100)}%`;$('#txPercent').textContent=`${Math.round(value*100)}%`;$('#txMessage').textContent=p.message||'Working…';if(p.partial)$('#txPartial').textContent=p.partial;$$('[data-phase]',modalBody).forEach(el=>el.classList.toggle('active',el.dataset.phase===p.phase));};
  $('#txRun').onclick=async()=>{
    const mode=modeEl.value,run=$('#txRun');controller=new AbortController();run.disabled=true;run.classList.add('working');
    try{
      let provider,options={durationUs:projectDuration(),draftText:$('#txDraft')?.value||'',language:$('#txLanguage').value};
      if(mode==='builtin'){
        if(!runtime.audioBlob)throw new Error('Import audio first.');
        const model=$('#txQuality').value==='accurate'?'onnx-community/whisper-small':$('#txQuality').value==='balanced'?'onnx-community/whisper-base':'onnx-community/whisper-tiny';
        provider=runtime.transcriptionProviderFactory?.({model})||new BrowserWhisperProvider({model});
      }else if(mode==='remote'){
        if(!runtime.audioBlob)throw new Error('Import audio first.');if(!$('#txConsent').checked)throw new Error('Upload consent is required for remote transcription.');provider=new WhisperRemoteProvider($('#txEndpoint').value,$('#txKey').value);
      }else provider=new LocalTimingAssistProvider();
      const events=await provider.transcribe(runtime.audioBlob,options,setProgress,controller.signal);
      const normalized=inferSections(events);state.commit(p=>{p.lyrics=normalized;p.instrumentalSections=instrumentalGaps(normalized);});
      setProgress({phase:'done',progress:1,message:`${events.length} editable lyric lines ready`,partial:normalized.map(e=>e.text).join('\n')});
      await new Promise(r=>setTimeout(r,350));modal.close();leftTab='lyrics';renderLeft();toast(`Generated ${events.length} editable lyric events`,'good');
    }catch(err){if(err?.name==='AbortError'){toast('Transcription cancelled');}else{setProgress({progress:0,message:err.message||'Transcription failed'});toast(err.message||'Transcription failed','bad');}}
    finally{run.disabled=false;run.classList.remove('working');controller=null;}
  };
}
function showExportModal(){const caps=videoCapabilities(),s=state.project.exportSettings,dur=projectDuration()/1e6,est=estimateOutputBytes(dur,s.videoBitrate,s.audioBitrate);modalBody.innerHTML=`<div class="modal-card"><h2>Export</h2><p class="subtle">Video is rendered from a separate composition-resolution canvas using the same renderer as preview. Codec availability depends on this browser.</p><div class="two-col"><label class="field"><span>Format</span><select id="exFormat"><option value="webm">WebM</option><option value="mp4" ${caps.mp4?'':'disabled'}>MP4 / H.264 ${caps.mp4?'':'(unsupported here)'}</option></select></label><label class="field"><span>Resolution</span><select id="exRes"><option>720p</option><option selected>1080p</option><option>1440p</option><option>4k</option></select></label><label class="field"><span>FPS</span><select id="exFps"><option>24</option><option selected>30</option><option>60</option></select></label><label class="field"><span>Video bitrate (Mbps)</span><input id="exVb" type="number" value="8" min="1" max="80"></label></div><p class="subtle">Estimated size at current duration: <b id="exEstimate">${bytes(est)}</b>. WebM: ${caps.webm?'supported':'not supported'} · MP4: ${caps.mp4?'supported':'not supported'} · WebCodecs: ${caps.webCodecs?'available':'unavailable'}.</p><div id="exProgress" class="hidden"><div class="progress"><i id="exBar"></i></div><p class="subtle" id="exMsg">Rendering…</p></div><div class="section"><h3>Video / audio</h3><div class="row"><button type="button" class="primary" id="exVideo">Export video</button><button type="button" id="exAudio" ${runtime.audioBlob?'':'disabled'}>Audio only</button></div></div><div class="section"><h3>Lyrics / project</h3><div class="row" style="flex-wrap:wrap"><button type="button" data-ex-sub="txt">TXT</button><button type="button" data-ex-sub="lrc">LRC</button><button type="button" data-ex-sub="srt">SRT</button><button type="button" data-ex-sub="vtt">VTT</button><button type="button" id="exProject">Project file</button></div></div><div class="modal-actions"><button value="cancel">Close</button></div></div>`;modal.showModal();const update=()=>{$('#exEstimate').textContent=bytes(estimateOutputBytes(dur,Number($('#exVb').value)*1e6,s.audioBitrate));};$('#exVb').oninput=update;$$('[data-ex-sub]',modalBody).forEach(b=>b.onclick=()=>downloadBlob(new Blob([exportLyrics(state.project.lyrics,b.dataset.exSub)],{type:'text/plain'}),`${state.project.name}.${b.dataset.exSub}`));$('#exProject').onclick=async()=>{const bundle=await createProjectBundle(state.project,getAsset);downloadBlob(bundle,`${state.project.name}.lyricforge`);};$('#exAudio').onclick=()=>downloadBlob(runtime.audioBlob,`${state.project.name}.${runtime.audioBlob.type.includes('wav')?'wav':'audio'}`);$('#exVideo').onclick=async()=>{const format=$('#exFormat').value,res=$('#exRes').value,fps=Number($('#exFps').value),vb=Number($('#exVb').value)*1e6;$('#exProgress').classList.remove('hidden');$('#exVideo').disabled=true;try{audio.pause();const result=await renderVideo({project:state.project,audioBlob:runtime.audioBlob,runtime:{assetElements:runtime.assetElements,frequencyData:()=>audio.frequencyData()},format,resolution:res,fps,videoBitrate:vb,audioBitrate:s.audioBitrate,onProgress:p=>{$('#exBar').style.width=`${Math.round(p*100)}%`;$('#exMsg').textContent=`Rendering ${Math.round(p*100)}%`;}});downloadBlob(result.blob,`${state.project.name}.${format==='mp4'?'mp4':'webm'}`);$('#exMsg').textContent=`Done · ${result.width}×${result.height}`;toast('Video export complete','good');}catch(err){$('#exMsg').textContent=err.message;toast(err.message,'bad');}finally{$('#exVideo').disabled=false;}};}

function showProjectMenu(){modalBody.innerHTML=`<div class="modal-card"><h2>Project</h2><p class="subtle">Create, open, save or duplicate the current LyricForge project.</p><div class="two-col"><button type="button" data-project-action="new">New project</button><button type="button" data-project-action="open">Open project</button><button type="button" class="primary" data-project-action="save">Save project</button><button type="button" data-project-action="save-as">Save As</button></div><div class="modal-actions"><button value="cancel">Close</button></div></div>`;modal.showModal();$$('[data-project-action]',modalBody).forEach(b=>b.onclick=()=>{const action=b.dataset.projectAction;modal.close();topAction(action);});}

function addMarker(){state.addMarker(state.playheadUs,`Marker ${state.project.markers.length+1}`);}
function frameStep(dir){const us=Math.round(1e6/state.project.composition.fps);state.setPlayhead(state.playheadUs+dir*us);audio.seekUs(state.playheadUs);}
function goLyric(dir){const {sorted,index}=activeLyricIndex();let i=index;if(i<0)i=0;i=Math.max(0,Math.min(sorted.length-1,i+dir));if(sorted[i]){state.setPlayhead(sorted[i].startUs);audio.seekUs(state.playheadUs);state.selectLyric(sorted[i].id);}}

async function topAction(action){
  if(action==='project-menu')showProjectMenu();
  if(action==='auto-transcribe'){leftTab='lyrics';renderLeft();showTranscriptionModal();}
  if(action==='new')showNewModal();if(action==='open')showOpenModal();if(action==='save')saveNow();if(action==='save-as'){const name=prompt('Project name',state.project.name);if(name){state.commit(p=>{p.id=uid('project');p.name=name;p.createdAt=new Date().toISOString();});saveNow();}}
  if(action==='undo')state.undo();if(action==='redo')state.redo();if(action==='export')showExportModal();if(action==='fullscreen'){if(document.fullscreenElement)document.exitFullscreen?.();else stage.requestFullscreen?.();}if(action==='toggle-guides'){runtime.guides=!runtime.guides;document.querySelector('[data-action="toggle-guides"]').classList.toggle('active',runtime.guides);renderFrame();}if(action==='fit-stage'){canvas.style.maxWidth='100%';canvas.style.maxHeight='100%';}
  if(action==='close-left-mobile')document.body.classList.remove('mobile-left-open');if(action==='close-timeline-mobile')document.body.classList.remove('mobile-timeline-open');if(action==='mobile-timeline'){const opening=!document.body.classList.contains('mobile-timeline-open');document.body.classList.toggle('mobile-timeline-open',opening);document.body.classList.remove('mobile-left-open','mobile-right-open');}if(action==='mobile-inspector'){const opening=!document.body.classList.contains('mobile-right-open');document.body.classList.toggle('mobile-right-open',opening);document.body.classList.remove('mobile-left-open','mobile-timeline-open','right-collapsed');const rb=document.querySelector('[data-action="collapse-right"]');if(rb)rb.textContent=opening?'×':'›';}if(action==='collapse-right'){if(isCompactMobile()){const opening=!document.body.classList.contains('mobile-right-open');document.body.classList.toggle('mobile-right-open',opening);document.body.classList.remove('mobile-left-open','right-collapsed');document.querySelector('[data-action="collapse-right"]').textContent=opening?'×':'›';}else document.body.classList.toggle('right-collapsed');}
  if(action==='play'){if(audio.playing)audio.pause();else await audio.play();syncPlayButtons();}if(action==='stop'){audio.stop();state.setPlayhead(0);syncPlayButtons();}if(action==='frame-back')frameStep(-1);if(action==='frame-forward')frameStep(1);if(action==='prev-lyric')goLyric(-1);if(action==='next-lyric')goLyric(1);if(action==='loop'){runtime.loopEnabled=!runtime.loopEnabled;const l=selectedLyric();runtime.loopRange=l?[l.startUs,l.endUs]:[0,projectDuration()];$('#loopButton').classList.toggle('active',runtime.loopEnabled);toast(runtime.loopEnabled?(l?'Looping selected lyric':'Looping composition'):'Loop off');}
  if(action==='timeline-select'||action==='timeline-razor'){state.commit(p=>{p.workspace.timelineTool=action==='timeline-razor'?'razor':'select';});renderTimeline();return;}
  if(action==='add-marker')addMarker();
  if(action==='split'){const c=selectedClip();if(c){try{state.commit(p=>Object.assign(p,splitClip(p,c.id,state.playheadUs)));toast('Clip split','good');}catch(err){toast(err.message,'bad')}}else state.splitSelected();}
  if(action==='ripple-delete'){const ids=[...state.selected.clips];if(ids.length){try{state.commit(p=>Object.assign(p,rippleDelete(p,ids)));state.selected.clips.clear();state.emit('selection');toast('Ripple delete complete','good');}catch(err){toast(err.message,'bad')}}}
  if(action==='toggle-keyframe'){const c=selectedClip();if(c){try{state.commit(p=>Object.assign(p,toggleKeyframeAt(p,c.id,'opacity',Math.max(0,state.playheadUs-c.startUs),c.opacity??1)));toast('Keyframe toggled','good');}catch(err){toast(err.message,'bad')}}}
  if(action==='duplicate')state.duplicateSelection();if(action==='delete')state.deleteSelection();
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b)topAction(b.dataset.action);const g=e.target.closest('[data-guide]');if(g){leftTab=g.dataset.guide==='adjust'?'effects':g.dataset.guide;renderLeft();}});
$$('.tool-rail button[data-tab]').forEach(b=>b.addEventListener('click',()=>{leftTab=b.dataset.tab;renderLeft();if(isCompactMobile()){document.body.classList.add('mobile-left-open');document.body.classList.remove('mobile-right-open','mobile-timeline-open');const rb=document.querySelector('[data-action="collapse-right"]');if(rb)rb.textContent='›';}}));
$$('[data-mobile-tab]').forEach(b=>b.addEventListener('click',()=>{leftTab=b.dataset.mobileTab;renderLeft();document.body.classList.add('mobile-left-open');document.body.classList.remove('mobile-right-open','mobile-timeline-open');const rb=document.querySelector('[data-action="collapse-right"]');if(rb)rb.textContent='›';}));
$('#previewSeek')?.addEventListener('input',e=>{state.setPlayhead(Number(e.target.value||0));audio.seekUs(state.playheadUs);});
$('#fileInput').addEventListener('change',e=>importFiles(e.target.files));
$('#playbackRate').addEventListener('change',e=>audio.setRate(Number(e.target.value)));
$('#volume').addEventListener('input',e=>audio.setVolume(Number(e.target.value)));
$('#timelineZoom').addEventListener('input',renderTimeline);$('#timelineTrackHeight')?.addEventListener('input',e=>{state.project.workspace.trackHeight=Number(e.target.value);renderTimeline();});$('#timelineTrackHeight')?.addEventListener('change',e=>state.commit(p=>{p.workspace.trackHeight=Number(e.target.value);}));
timelineScroll.addEventListener('scroll',()=>{$('#trackHeaders').scrollTop=timelineScroll.scrollTop;});

for(const ev of ['dragenter','dragover'])document.addEventListener(ev,e=>{e.preventDefault();$('#dropOverlay').classList.add('show');});for(const ev of ['dragleave','drop'])document.addEventListener(ev,e=>{e.preventDefault();if(ev==='drop'){const fs=e.dataTransfer?.files;if(fs?.length)importFiles(fs);}$('#dropOverlay').classList.remove('show');});

window.addEventListener('keydown',async e=>{const tag=document.activeElement?.tagName;if(['INPUT','TEXTAREA','SELECT'].includes(tag))return;const mod=e.ctrlKey||e.metaKey;if(e.code==='Space'){e.preventDefault();topAction('play');}else if(mod&&e.key.toLowerCase()==='z'&&e.shiftKey){e.preventDefault();state.redo();}else if(mod&&e.key.toLowerCase()==='z'){e.preventDefault();state.undo();}else if(mod&&e.key.toLowerCase()==='s'){e.preventDefault();saveNow();}else if(mod&&e.key.toLowerCase()==='c')state.copySelection();else if(mod&&e.key.toLowerCase()==='v')state.paste();else if(mod&&e.key.toLowerCase()==='d'){e.preventDefault();state.duplicateSelection();}else if(e.key==='Delete'||e.key==='Backspace')state.deleteSelection();else if(e.key==='ArrowLeft'){state.setPlayhead(state.playheadUs-(e.shiftKey?100_000:10_000));audio.seekUs(state.playheadUs);}else if(e.key==='ArrowRight'){state.setPlayhead(state.playheadUs+(e.shiftKey?100_000:10_000));audio.seekUs(state.playheadUs);}else if(e.key.toLowerCase()==='s')state.splitSelected();else if(e.key.toLowerCase()==='m')addMarker();});
window.addEventListener('beforeunload',e=>{if(state.dirty){e.preventDefault();e.returnValue='';}});

function setupPanelResizer(el,side){let startX=0,start=0;el.addEventListener('pointerdown',e=>{startX=e.clientX;start=parseFloat(getComputedStyle(document.documentElement).getPropertyValue(side==='left'?'--left':'--right'))||330;el.setPointerCapture?.(e.pointerId);const move=ev=>{const delta=ev.clientX-startX;const v=Math.max(210,Math.min(520,start+(side==='left'?delta:-delta)));document.documentElement.style.setProperty(side==='left'?'--left':'--right',`${v}px`);};const up=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);};window.addEventListener('pointermove',move);window.addEventListener('pointerup',up);});}
setupPanelResizer($('#leftResizer'),'left');setupPanelResizer($('#rightResizer'),'right');
let pinchDistance=null,pinchZoom=null;timelineScroll.addEventListener('touchstart',e=>{if(e.touches.length===2){pinchDistance=Math.hypot(e.touches[0].clientX-e.touches[1].clientX,e.touches[0].clientY-e.touches[1].clientY);pinchZoom=Number($('#timelineZoom').value);}}, {passive:true});timelineScroll.addEventListener('touchmove',e=>{if(e.touches.length===2&&pinchDistance){const d=Math.hypot(e.touches[0].clientX-e.touches[1].clientX,e.touches[0].clientY-e.touches[1].clientY);const z=Math.max(.35,Math.min(6,pinchZoom*d/pinchDistance));$('#timelineZoom').value=z;renderTimeline();}}, {passive:true});timelineScroll.addEventListener('touchend',()=>{pinchDistance=null;pinchZoom=null;},{passive:true});


async function boot(){if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});installedPresets=await listInstalledPresets().catch(()=>[]);renderLeft();renderInspector();renderTimeline();updateTime();renderFrame();loadWebFontsForProject();playbackLoop();try{const last=await lastProject();if(last){await loadIntoEditor(last);toast(`Reopened ${last.name}`,'good');}}catch(e){console.warn('Could not restore last project',e);}window.__LYRICFORGE__={state,audio,runtime,importFiles,renderFrame,renderSelectionOverlay,applyPreviewPinch,refreshPresetCatalog,refreshInstalledPresets};}
boot();
